<?php account_page_start('Ticket #'.(int)$ticket['id'],'support','SUPPORT TICKET #'.(int)$ticket['id'],(string)$ticket['subject'],'',store_t(ucfirst((string)$ticket['category'])).' · '.store_order_status_t((string)$ticket['status']),$user); ?>
<?php if($message):?><div class="app-alert dashboard-alert success"><?=htmlspecialchars($message,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($error):?><div class="app-alert dashboard-alert danger"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?>
<?php $lastSupportMessageId=0;foreach($messages as $messageRow){$lastSupportMessageId=max($lastSupportMessageId,(int)($messageRow['id']??0));} ?>
<section class="app-panel dashboard-card tool-card"><div class="support-thread" data-support-thread data-ticket-id="<?=(int)$ticket['id']?>" data-poll-url="<?=htmlspecialchars(route_url('support-thread.php'),ENT_QUOTES,'UTF-8')?>" data-last-message-id="<?=$lastSupportMessageId?>"><?php foreach($messages as $m):?><article class="support-message <?=$m['sender_is_admin']?'is-admin':'is-user'?>"><div class="support-message-head"><strong><?= $m['sender_is_admin']?store_h(store_t('SUPPORT')):htmlspecialchars((string)($m['username']??store_t('USER')),ENT_QUOTES,'UTF-8')?></strong><?=web_local_datetime($m['created_at']??null,store_t('Unknown'))?></div><?php if(!empty($m['message'])):?><p><?=nl2br(htmlspecialchars((string)$m['message'],ENT_QUOTES,'UTF-8'))?></p><?php endif;?><?php if(!empty($m['attachment_stored_name'])):?><a class="app-button tool-button secondary" href="<?=htmlspecialchars(route_url('support-attachment.php').'?id='.(int)$m['id'],ENT_QUOTES,'UTF-8')?>"><?=store_h(store_t('DOWNLOAD'))?> <?=htmlspecialchars((string)$m['attachment_original_name'],ENT_QUOTES,'UTF-8')?> ↓</a><?php endif;?></article><?php endforeach;?></div></section>
<?php if((string)$ticket['status']!=='closed'):?><section class="app-panel dashboard-card tool-card"><div class="tool-heading"><div><p class="card-kicker"><?=store_h(store_t('REPLY'))?></p><h2><?=store_h(store_t('Add information or diagnostics'))?></h2></div></div><form method="post" enctype="multipart/form-data" class="security-form support-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$ticket['id']?>"><label><span><?=store_h(store_t('MESSAGE'))?></span><textarea name="message" rows="5" maxlength="8000"></textarea></label><?php if($canDiagnostics):?><label><span><?=store_h(store_t('ATTACHMENT · OPTIONAL'))?></span><input type="file" name="diagnostics" accept=".zip,.log,.txt,.json"></label><?php endif;?><button class="app-button tool-button primary" type="submit"><?=store_h(store_t('SEND REPLY'))?> ↗</button></form></section><?php endif;?>
<?php account_page_end('SUPPORT'); ?>
